-- =====================================================================
-- ماتریس تست جامع سیستم (Comprehensive Test Matrix Data)
--
-- این فایل از وضعیت «پر شده» پایگاه داده بازتولید شده است: هر خانه‌ای که
-- در فورم‌های سیستم قابل ورود است، در اینجا مقدار دارد تا بتوان بخش به بخش
-- رابط کاربری را بررسی کرد.
--
-- دامنه: فقط پروژه‌های با کد TM-*، کاربران با پیشوند tm_ و شرکت‌های آنان.
-- داده‌های اصلی install.sql دست‌نخورده و از این فایل مستثنی هستند.
--
-- ★ این فایل «دوباره‌اجراشدنی» است و خطای #1062 (Duplicate entry) نمی‌دهد:
--     • هیچ شناسه‌ی اصلی (id) به‌صورت عدد ثابت نوشته نشده؛ شناسه‌ها را خودِ
--       MySQL با AUTO_INCREMENT می‌سازد و کلیدهای خارجی با متغیرهای
--       LAST_INSERT_ID() به هم وصل می‌شوند. بنابراین مهم نیست در پایگاه داده‌ی
--       مقصد چه شناسه‌هایی اشغال شده باشد.
--     • پیش از درج، داده‌های همین دامنه پاک می‌شوند (فرزند ← والد، با کلید
--       خارجیِ روشن تا ON DELETE CASCADE درست کار کند)، پس ایمپورتِ دوباره‌ی
--       فایل بی‌ضرر است.
--
-- تنها اثر جانبی: چون users.company_id کلید خارجیِ ON DELETE SET NULL دارد،
-- اگر کاربری *بیرون* از این دامنه (مثلاً admin) به یکی از شرکت‌های ماتریس وصل
-- باشد، با پاک‌سازی، company_id او NULL می‌شود. در نصبِ استاندارد همین‌طور است
-- (install.sql کاربر admin را بدون company_id می‌سازد)، پس چیزی از دست نمی‌رود.
--
-- ترتیب اجرا:  install.sql  →  schema_v2.sql  →  schema_v3.sql  →  این فایل
-- (sample_test_data.sql اختیاری است و با این فایل تداخل ندارد.)
--
-- پوشش:
--   • هر ۵ سطح دسترسی (RBAC) + یک کاربر غیرفعال
--   • هر دو واحد پولی (AFN و USD) در همه‌ی جدول‌های مالی
--   • تمام مقدار‌های ممکن هر ستون ENUM در همه‌ی جدول‌ها
--   • تمام ۵ نوع کهاته (S/M/P/C/V) + کهاته غیرفعال + مانده منفی
--   • تاریخ شمسی سازگار با تقویم واقعی (نوروز ۱۴۰۵ = ۲۰۲۶-۰۳-۲۱)
--   • ضمیمه‌ی واقعی (PDF/PNG) برای هر رکوردِ دارای فیلد فایل
--   • حاضری روزانه برای هر پروژه (شامل امروز) تا گزارش ماهانه داده داشته باشد
--
-- NULL فقط در مواردی که مقدارگذاری با خود رکورد در تضاد است باقی مانده:
--   employees.termination_date  -> فقط برای کارمندانی با status='terminated'
--   contracts.customer_id       -> فقط برای party_type='customer'
--   contracts.kahta_account_id  -> فقط برای party_type='kahta'
--
-- رمز عبور همه‌ی کاربران tm_* برابر است با:  Test@2026
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 1;

-- ---------------------------------------------------------------
-- ۱) پاک‌سازی دامنه‌ی این فایل (اگر قبلاً ایمپورت شده باشد)
--    شناسه‌ی شرکت‌های ماتریس پیش از حذف پروژه‌ها ذخیره می‌شود، چون بعد از
--    حذف پروژه‌ها دیگر راهی برای تشخیص آن‌ها نیست.
-- ---------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS `_tm_company_ids`;
CREATE TEMPORARY TABLE `_tm_company_ids` AS
  SELECT DISTINCT company_id AS id FROM projects WHERE code LIKE 'TM-%';

DELETE FROM `audit_log` WHERE username LIKE 'tm\\_%';
DELETE FROM `employee_leaves` WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%');
DELETE FROM `employee_attendance` WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%');
DELETE FROM `employees` WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%');
DELETE FROM `contract_machinery` WHERE contract_id IN (SELECT id FROM contracts WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%'));
DELETE FROM `machinery` WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%');
DELETE FROM `contracts` WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%');
DELETE FROM `customers` WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%');
DELETE FROM `revenue_to_sarafi` WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%');
DELETE FROM `kahta_advances` WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%');
DELETE FROM `expenses` WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%');
DELETE FROM `money_receipts` WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%');
DELETE FROM `kahta_accounts` WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%');
DELETE FROM `user_projects` WHERE user_id IN (SELECT id FROM users WHERE username LIKE 'tm\\_%') OR project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%');
DELETE FROM `users` WHERE username LIKE 'tm\\_%';
DELETE FROM `projects` WHERE code LIKE 'TM-%';
DELETE FROM `sarafi_companies` WHERE company_id IN (SELECT id FROM _tm_company_ids);
DELETE FROM `companies` WHERE id IN (SELECT id FROM _tm_company_ids);

